import{_ as n,C as i,o as a,c as r,E as o,a2 as s}from"./chunks/framework.Cm6XCzck.js";const l="/joinwell52/assets/figures/2026-08-28-event-consumer-projection.en.svg",v=JSON.parse('{"title":"CodeFlowMu Engineering Record (III): An Event Happened — But Who Should See What? Designing a Safe Activity Projection Boundary","description":"","frontmatter":{"title":"CodeFlowMu Engineering Record (III): An Event Happened — But Who Should See What? Designing a Safe Activity Projection Boundary","date":"2026-08-28","updated":"2026-08-31","column":"open-source-engineering","category":"daily","article_type":"comparative-technical-analysis","edition":"research-center","research_question":"When internal Activity must retain complete facts, how should the Runtime ensure that ordinary consumers receive only contract-approved fields instead of inheriting the complete internal payload?","summary":"Historical CodeFlowMu Activity data and a real query probe showed that complete internal payloads could cross an ordinary consumption boundary. V2.1.2 separates internal event storage from consumer projection and reconstructs ordinary Web Panel, Activity API and Analytics objects through server-side recursive allowlists. payload.raw, unknown fields and unknown nested values are hidden by default; independent QA observed the raw marker 0 times in the ordinary projection.","sources":"/en/research/evidence/2026-08-28-event-consumer-visibility","project_relevance":"substantive-relationship","item_id":"RBE-20260828-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-28-event-consumer-visibility-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-08-28-event-consumer-visibility.md","filePath":"en/engineering/2026-08-28-event-consumer-visibility.md","lastUpdated":1788148073000}'),d={name:"en/engineering/2026-08-28-event-consumer-visibility.md"};function c(h,e,p,u,m,y){const t=i("ArticleCover");return a(),r("div",null,[o(t,{image:"/assets/covers/daily-2026-08-28-event-consumer-visibility-cover.png",kicker:"CodeFlowMu Engineering Record · 03",title:"An Event Happened — But Who Should See What? Designing a Safe Activity Projection Boundary",summary:"Observability is not pass-through. Internal events may retain complete evidence, while ordinary consumers should receive only explicitly registered safe projections.",version:"RBE-20260828-02",status:"Engineering Analysis · Revised 2026-08-31",languageHref:"/zh/engineering/2026-08-28-event-consumer-visibility",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="codeflowmu-engineering-record-iii-an-event-happened-—-but-who-should-see-what-designing-a-safe-activity-projection-boundary" tabindex="-1">CodeFlowMu Engineering Record (III): An Event Happened — But Who Should See What? Designing a Safe Activity Projection Boundary <a class="header-anchor" href="#codeflowmu-engineering-record-iii-an-event-happened-—-but-who-should-see-what-designing-a-safe-activity-projection-boundary" aria-label="Permalink to &quot;CodeFlowMu Engineering Record (III): An Event Happened — But Who Should See What? Designing a Safe Activity Projection Boundary&quot;">​</a></h1><p>An auditable Agent Runtime often cannot store only the small amount of information needed by a user interface.</p><p>Diagnostics may need original tool output, Host events, internal state and context. Failure analysis may require more facts than an ordinary panel should ever receive.</p><p>That immediately creates another boundary:</p><blockquote><p><strong>Are the facts the system must retain internally the same object that an ordinary consumer is entitled to receive?</strong></p></blockquote><h2 id="what-is-codeflowmu-and-why-is-activity-more-than-logging" tabindex="-1">What is CodeFlowMu, and why is Activity more than “logging”? <a class="header-anchor" href="#what-is-codeflowmu-and-why-is-activity-more-than-logging" aria-label="Permalink to &quot;What is CodeFlowMu, and why is Activity more than “logging”?&quot;">​</a></h2><p>CodeFlowMu is a <strong>local-first multi-agent collaboration and digital-employee runtime</strong>. Agents with different responsibilities execute work continuously while the Runtime manages tasks, Sessions, tool calls, state transitions, recovery and audit evidence.</p><p>In such a system, Activity/Event data is not merely UI logging. It serves several roles at once: the Runtime needs to know what happened; EVAL and QA need evidence for review; diagnostics may need deeper Host or tool-native facts; Web Panel, ordinary APIs and Analytics need only the subset required for their own responsibilities.</p><p>CodeFlowMu therefore has to satisfy two requirements at the same time:</p><ul><li><strong>internal facts should remain sufficiently complete for recovery and audit;</strong></li><li><strong>ordinary consumers should receive the minimum visibility required by their contract.</strong></li></ul><p>That is the safe-projection boundary studied here.</p><p>If internal event objects and ordinary consumer objects are identical, observability easily turns into data pass-through. A new field entering an internal <code>payload</code> can unintentionally propagate through Activity API, Web Panel, Analytics or logging consumers.</p><p>Historical CodeFlowMu events contained raw payloads at scale, and a minimal first-party query probe later showed that a marker stored only in <code>payload.raw</code> could cross the ordinary Activity query boundary.</p><p>We do not describe that fact as proof of a data breach. Whether unauthorized access actually occurred depends on deployment, authentication, network reachability and access records. The narrower conclusion supported by first-party evidence is:</p><p><strong>the boundary between complete internal events and ordinary consumers lacked a structured, fail-closed field-projection contract.</strong></p><p>For historical data, probe results, version boundaries and public evidence, see <a href="/joinwell52/en/research/evidence/2026-08-28-event-consumer-visibility">RBE-20260828-02</a>.</p><h2 id="external-research-origin-a-new-event-entering-the-bus-should-not-automatically-gain-every-old-consumer" tabindex="-1">External research origin: a new event entering the bus should not automatically gain every old consumer <a class="header-anchor" href="#external-research-origin-a-new-event-entering-the-bus-should-not-automatically-gain-every-old-consumer" aria-label="Permalink to &quot;External research origin: a new event entering the bus should not automatically gain every old consumer&quot;">​</a></h2><p>The external comparison is <a href="https://github.com/OpenHands/software-agent-sdk/pull/4689" target="_blank" rel="noreferrer">OpenHands SDK PR #4689</a>, which addressed <code>StreamingDeltaEvent</code> being delivered by default to consumers that did not need it.</p><p>Different consumers shared one event bus, but their responsibilities differed: ordinary event subscriptions, auto-title generation, Webhooks, Telemetry and WebSocket clients did not need the same granularity. Token-level streaming deltas were genuinely needed by WebSocket consumers, yet generic subscription behavior caused other consumers to inherit the new event type automatically.</p><p>The PR reported this end-to-end contrast:</p><table tabindex="0"><thead><tr><th>Metric</th><th style="text-align:right;">Before</th><th style="text-align:right;">After</th></tr></thead><tbody><tr><td>HTTP POST</td><td style="text-align:right;">41</td><td style="text-align:right;">1</td></tr><tr><td>Webhook-delivered events</td><td style="text-align:right;">201</td><td style="text-align:right;">3</td></tr><tr><td><code>StreamingDeltaEvent</code> among them</td><td style="text-align:right;">198</td><td style="text-align:right;">0</td></tr></tbody></table><p>The <strong>41 → 1</strong> result belongs to the OpenHands test, not to CodeFlowMu performance.</p><p>The broader lesson is a consumer-boundary principle:</p><p><strong>Adding an event capability to a shared bus should not automatically expand the visibility of every existing consumer.</strong></p><p>OpenHands addressed which consumers receive an event type. CodeFlowMu later encountered the adjacent question: even when a consumer is entitled to receive an Activity, <strong>should it receive every field of that event?</strong></p><p>The former is an event-subscription boundary. The latter is a field-visibility boundary.</p><h2 id="historical-data-raw-was-common-but-that-alone-does-not-prove-current-exposure" tabindex="-1">Historical data: raw was common, but that alone does not prove current exposure <a class="header-anchor" href="#historical-data-raw-was-common-but-that-alone-does-not-prove-current-exposure" aria-label="Permalink to &quot;Historical data: raw was common, but that alone does not prove current exposure&quot;">​</a></h2><p>The CodeFlowMu historical profile covered 27 JSONL files and 20,440 parseable rows:</p><table tabindex="0"><thead><tr><th>Dataset</th><th style="text-align:right;">Rows</th><th style="text-align:right;">With <code>payload.raw</code></th><th style="text-align:right;">Share</th></tr></thead><tbody><tr><td>Runtime</td><td style="text-align:right;">2,743</td><td style="text-align:right;">1,474</td><td style="text-align:right;">53.7%</td></tr><tr><td>Analytics</td><td style="text-align:right;">17,697</td><td style="text-align:right;">16,828</td><td style="text-align:right;">95.1%</td></tr><tr><td>Total</td><td style="text-align:right;">20,440</td><td style="text-align:right;">18,302</td><td style="text-align:right;">89.5%</td></tr></tbody></table><p>These numbers are easy to overread.</p><p>They establish only that <strong>raw payloads were common in historical artifacts spanning different implementation phases</strong>.</p><p>They do not prove that a particular current V2.0.4, V2.1.1 or V2.1.2 query endpoint returns those fields, and they do not prove that an unauthorized user actually read them.</p><p>A later subset also provides an important counterexample: 681 Analytics rows from August 10 and 12 had <code>payload.raw=0</code>. Some paths had already improved, but that still did not establish a fail-closed field contract across all consumers.</p><p>Storage history answers “what did the system keep?”</p><p>To evaluate the consumer boundary, we needed a second question:</p><p><strong>What does an ordinary query actually return?</strong></p><h2 id="a-marker-that-exists-only-in-raw-isolates-the-problem-at-the-query-boundary" tabindex="-1">A marker that exists only in raw isolates the problem at the query boundary <a class="header-anchor" href="#a-marker-that-exists-only-in-raw-isolates-the-problem-at-the-query-boundary" aria-label="Permalink to &quot;A marker that exists only in raw isolates the problem at the query boundary&quot;">​</a></h2><p>To avoid inferring current behavior directly from historical files, the first-party experiment used a minimal query probe.</p><p>A unique marker was placed only inside <code>payload.raw</code>, then exercised through the real ActivityBuffer path:</p><p><code>ActivityBuffer.push() → ActivityBuffer.query() → serialize → marker check</code></p><p>On the tested V2.0.4 path, the serialized ordinary query still contained the marker. A pre-fix rerun on V2.1.1 baseline <code>36e5c83b</code> confirmed the same behavior.</p><p>That result is enough to establish one concrete fact:</p><p><strong>field minimization was not mechanically enforced at that ordinary query boundary.</strong></p><p>It still does not prove unauthorized access occurred.</p><p>The gap becomes clearer when responsibilities are separated into three layers:</p><ul><li><strong>producer</strong>: creates a complete internal event;</li><li><strong>internal storage</strong>: decides which raw facts should be retained for diagnostics and audit;</li><li><strong>consumer boundary</strong>: decides which fields a given consumer should actually receive.</li></ul><p>Retaining raw internally is not inherently wrong. The risk appears when the third layer has no independent contract and “visible internally” silently becomes “visible to ordinary consumers.”</p><h2 id="engineering-judgment-observability-is-not-copying-the-same-object-everywhere" tabindex="-1">Engineering judgment: observability is not copying the same object everywhere <a class="header-anchor" href="#engineering-judgment-observability-is-not-copying-the-same-object-everywhere" aria-label="Permalink to &quot;Engineering judgment: observability is not copying the same object everywhere&quot;">​</a></h2><p>Many systems begin with Activity/Event as a debugging feature. The simplest implementation is to construct one complete object and return it to whoever asks.</p><p>As the system grows, that design creates hidden coupling:</p><ol><li>Panel begins depending on one internal field;</li><li>Analytics reads another unregistered field;</li><li>a new Host adds nested payload structure;</li><li>a log center reuses the complete object for convenience;</li><li>nobody can safely remove raw because it is unclear which consumer has begun depending on it.</li></ol><p>The event bus has effectively turned the Runtime&#39;s internal data structure into a public API.</p><p>V2.1.2 therefore adopts a more basic rule before attempting to classify every value as sensitive or non-sensitive:</p><blockquote><p><strong>The internal event is the fact object. The consumer receives a projection object. They are not the same data contract.</strong></p></blockquote><p>This turns minimization from an ad hoc content filter into an architectural boundary.</p><h2 id="why-a-blacklist-is-insufficient-future-unknown-fields-do-not-register-themselves" tabindex="-1">Why a blacklist is insufficient: future unknown fields do not register themselves <a class="header-anchor" href="#why-a-blacklist-is-insufficient-future-unknown-fields-do-not-register-themselves" aria-label="Permalink to &quot;Why a blacklist is insufficient: future unknown fields do not register themselves&quot;">​</a></h2><p>A common fix looks like this:</p><p><code>copy(event.payload) → delete raw → delete secret → delete prompt</code></p><p>It can work for fields known today.</p><p>But a blacklist has no knowledge of tomorrow&#39;s <code>payload.debug.original</code>, a new Host&#39;s <code>native_payload</code>, a new event type, or another nested layer of raw data. Unknown fields can cross the boundary until someone notices and adds another delete rule.</p><p>V2.1.2 therefore reverses the model and uses a <strong>recursive allowlist</strong>:</p><ul><li>for known events, reconstruct only registered fields;</li><li>new top-level fields are absent until explicitly registered;</li><li>new nested fields are absent until explicitly registered;</li><li>unknown event types do not pass unknown payloads through and keep only the allowed public envelope;</li><li><code>payload.raw</code> is not part of ordinary consumer projection;</li><li>each consumer gets a new projection object rather than a shared reference to a more privileged internal object.</li></ul><p>This is fail-closed visibility semantics.</p><p>When the system does not know whether a new field belongs in an ordinary consumer contract, the default answer is not “send it first.” The default is “do not expose it until the contract explicitly expands.”</p><h2 id="v2-1-2-determine-the-consumer-on-the-server-then-reconstruct-by-contract" tabindex="-1">V2.1.2: determine the consumer on the server, then reconstruct by contract <a class="header-anchor" href="#v2-1-2-determine-the-consumer-on-the-server-then-reconstruct-by-contract" aria-label="Permalink to &quot;V2.1.2: determine the consumer on the server, then reconstruct by contract&quot;">​</a></h2><p>An allowlist only matters if the consumer identity is itself trustworthy.</p><p>If a client can simply send <code>?consumer=internal_debug</code> and upgrade itself to a privileged projection, field rules do not provide a meaningful boundary.</p><p>V2.1.2 therefore binds ordinary consumer policy at server entry points. The delivered scope covers Web Panel, Activity API and Analytics-style ordinary consumers. Analytics and log-center consumption follow the same safe-projection principle so that tightening one path does not leave a raw-object bypass through another.</p><p>The core flow is:</p><p><code>internal Activity → server-bound consumer identity → event-type rule → recursive safe projection → consumer object</code></p><table tabindex="0"><thead><tr><th>Consumer path</th><th>Preserve</th><th>Deny by default</th></tr></thead><tbody><tr><td>Web Panel</td><td>registered status, role, task, session, event and controlled summaries</td><td><code>payload.raw</code>, unknown fields, unknown nested values</td></tr><tr><td>Activity API</td><td>approved envelope and event-specific payload projection</td><td>complete internal payload and unregistered extensions</td></tr><tr><td>Analytics / log consumption</td><td>registered structured fields needed for analysis and diagnosis</td><td>raw-object pass-through and data outside the consumer contract</td></tr></tbody></table><p>Approved relational fields such as task, thread, session, event and <code>projected_summary</code> remain available.</p><p>That matters: the goal of safe projection is not to make events empty. It is to retain the minimum structured facts a consumer needs to perform its job.</p><p>Raw internal events are not deleted. Explicitly authorized diagnostics can still use them through internal paths; ordinary API and analytics consumers receive projections.</p><p>That is how complete internal evidence and least-visible ordinary consumption can coexist.</p><p><img src="'+l+'" alt="V2.1.2 server-side recursive projections for three ordinary consumers"></p><p><em>Figure 1. V2.1.2 separates complete internal events from ordinary consumer projections. Unknown event payloads, unregistered fields and unknown nested values do not enter the result by default. Source: <a href="/joinwell52/en/research/evidence/2026-08-28-event-consumer-visibility">RBE-20260828-02</a>.</em></p><h2 id="the-first-regression-failed-minimization-can-also-delete-what-the-system-genuinely-needs" tabindex="-1">The first regression failed: minimization can also delete what the system genuinely needs <a class="header-anchor" href="#the-first-regression-failed-minimization-can-also-delete-what-the-system-genuinely-needs" aria-label="Permalink to &quot;The first regression failed: minimization can also delete what the system genuinely needs&quot;">​</a></h2><p>Safe projection does not mean “fewer fields is always better.”</p><p>After the first pruning implementation, the targeted Shell regression was <strong>19 pass / 1 fail</strong>. One semantic warning that the log center should have displayed dropped from 1 to 0.</p><p>The repair was not to restore raw. The first projection had removed a diagnostic state signal that was genuinely needed and could be safely derived.</p><p>The final projection explicitly derived and allowed only:</p><p><code>ok / code / summary_blocked_reason / projection_status</code></p><p>The targeted rerun reached <strong>20/20</strong> without restoring full summary/raw pass-through.</p><p>This failed intermediate result is valuable evidence because it blocks another overbroad claim:</p><p><strong>“The more fields you delete, the safer the system becomes.”</strong></p><p>If minimization prevents Panel or diagnostics from seeing a real failure signal, the system may expose less data while also becoming less diagnosable.</p><p>A mature projection contract has to test both directions: prohibited fields really do not leave the boundary, and the status, relation keys and warnings required by the consumer still survive.</p><h2 id="safe-projection-is-not-a-sensitive-content-classifier" tabindex="-1">Safe projection is not a sensitive-content classifier <a class="header-anchor" href="#safe-projection-is-not-a-sensitive-content-classifier" aria-label="Permalink to &quot;Safe projection is not a sensitive-content classifier&quot;">​</a></h2><p>V2.1.2 establishes structural visibility boundaries. It is not a model that understands whether every possible string is semantically sensitive.</p><p>Recursive allowlisting ensures that unregistered fields, unknown nested values and raw do not automatically cross an ordinary boundary when internal objects evolve.</p><p>But if a producer writes inappropriate content into a string field that is already approved by the consumer contract, the projector does not magically infer that the string contains a secret.</p><p>Responsibilities remain separate:</p><ul><li>producers must obey content contracts;</li><li>the projector enforces structural minimization and fail-closed handling of unknown fields;</li><li>authentication/authorization decides who may call a consumer endpoint;</li><li>network/deployment boundaries decide whether an endpoint is reachable;</li><li>internal diagnostic authorization decides who may read complete raw events.</li></ul><p>Those layers do not prove one another.</p><p>The engineering claim is therefore “ordinary consumers no longer inherit complete internal payloads by default,” not “the entire Runtime can never disclose information.”</p><h2 id="independent-qa-the-raw-marker-must-disappear-while-correlation-facts-remain" tabindex="-1">Independent QA: the raw marker must disappear while correlation facts remain <a class="header-anchor" href="#independent-qa-the-raw-marker-must-disappear-while-correlation-facts-remain" aria-label="Permalink to &quot;Independent QA: the raw marker must disappear while correlation facts remain&quot;">​</a></h2><p>Independent QA B1 constructed a unique marker present only in raw and checked the ordinary projection.</p><table tabindex="0"><thead><tr><th>Check</th><th>Independent QA result</th></tr></thead><tbody><tr><td>raw-marker occurrences in ordinary projection</td><td><strong>0</strong></td></tr><tr><td><code>raw_present</code></td><td><code>false</code></td></tr><tr><td>event count</td><td>1</td></tr><tr><td>event_type / task_id / session_id</td><td>preserved and matched input</td></tr><tr><td><code>projected_summary</code></td><td>controlled summary preserved</td></tr></tbody></table><p>The scenario validates both sides of the contract:</p><ol><li>the prohibited raw marker did not cross the ordinary consumer boundary;</li><li>pruning did not destroy the necessary correlation facts.</li></ol><p>Unknown events, new nested fields, per-consumer object isolation, server-side consumer selection and Analytics persistence also have targeted tests.</p><p>B1 still must not be expanded into a claim that real LAN/Gateway clients, every deployment mode and every future event have all received independent validation. It independently validates a critical boundary in the tested ordinary-projection contract.</p><h2 id="what-this-means-for-a-digital-employee-runtime" tabindex="-1">What this means for a digital-employee runtime <a class="header-anchor" href="#what-this-means-for-a-digital-employee-runtime" aria-label="Permalink to &quot;What this means for a digital-employee runtime&quot;">​</a></h2><p>Activity visibility is not only a privacy concern. It directly affects whether an Agent Runtime can evolve safely.</p><p>If every consumer reads the complete internal object, any new Host, Tool or Agent field can accidentally change Panel rendering, Analytics counts, log volume, API schemas, downstream dependencies and information-exposure surface.</p><p>That makes internal implementation difficult to evolve because an internal field change can silently become a public-interface change.</p><p>Safe projection also provides <strong>decoupling</strong>.</p><p>Internal events can gain richer diagnostic facts while ordinary consumers receive new fields only after explicit registration. “The Runtime knows more” no longer automatically means “every downstream consumer receives more.”</p><p>For a long-running digital-employee system that continually adds Hosts, Tools and Agents, that default non-propagation matters.</p><p>Mature observability is not “everything is visible everywhere.” It is:</p><p><strong>each consumer can see the facts required for its responsibility, and cannot see internal state for which it has no contract basis.</strong></p><h2 id="from-engineering-patch-to-formal-version" tabindex="-1">From engineering patch to formal version <a class="header-anchor" href="#from-engineering-patch-to-formal-version" aria-label="Permalink to &quot;From engineering patch to formal version&quot;">​</a></h2><p>CodeFlowMu V2.1.2 was released on August 30, 2026. Its Runtime and Shell source code is maintained in a private repository. Activity safe projection shipped together with persistent task idempotency and Session identity verification as one Runtime boundary-safety patch.</p><p>Public articles do not send readers to inaccessible private CodeFlowMu repository links. Publicly reviewable version facts, sanitized B1 results, compatibility and residual risks are available in the <a href="/joinwell52/en/research/evidence/2026-08-28-event-consumer-visibility">public evidence pack</a> and the <a href="/joinwell52/en/research/evidence/2026-08-30-codeflowmu-v2.1.2-public-release-summary">V2.1.2 Public Release Summary</a>.</p><p>Final release validation recorded:</p><ul><li>Runtime: <strong>1842 pass / 0 fail / 1 skip</strong>;</li><li>Shell: <strong>1037 pass / 0 fail / 0 skip</strong>;</li><li>V2.1.1 and V2.1.2 same-protocol critical matrices, ten consecutive rounds each: Runtime <strong>1630/1630</strong>, Shell <strong>550/550</strong>;</li><li>typecheck, Shell build, installer contract, rules and version consistency passed.</li></ul><p>R1/R2 failure evidence remains preserved rather than overwritten by the final R3 pass, including lockfile issues, the independent Open Edition build boundary and the over-pruning regression described above.</p><p>The release does not include an independent Open Dev Team Edition and does not pretend that real browser profiles, LAN/Gateway deployments or user production projects were covered by the fixtures. The Windows symlink-permission skip and existing dependency warnings remain explicit.</p><h2 id="a-review-checklist-for-other-agent-runtimes" tabindex="-1">A review checklist for other Agent Runtimes <a class="header-anchor" href="#a-review-checklist-for-other-agent-runtimes" aria-label="Permalink to &quot;A review checklist for other Agent Runtimes&quot;">​</a></h2><p>When reviewing Event / Activity consumer boundaries, ask:</p><ol><li>Are internal storage objects and ordinary consumer objects the same structure?</li><li>Is consumer identity bound by the server, or can a caller self-assert a more privileged consumer?</li><li>Is projection recursive allowlisting, or full-object copy followed by a short denylist?</li><li>Are new event types and nested fields hidden by default until registered?</li><li>Are raw tool output and Host-private structures restricted to explicitly authorized diagnostic paths?</li><li>Are necessary task/thread/session/event correlation facts still preserved?</li><li>Do Analytics, logging, Panel and API follow the same safe-projection principle, or do bypasses remain?</li><li>Does each consumer receive an independent object rather than a shared reference to a privileged internal object?</li><li>Does QA test both “prohibited field count = 0” and “required fields still exist”?</li><li>Are internal-data existence, ordinary-interface visibility and real unauthorized access kept as three distinct claims?</li></ol><p>These questions tell us much more than simply asking whether <code>raw</code> was deleted.</p><h2 id="engineering-conclusion" tabindex="-1">Engineering conclusion <a class="header-anchor" href="#engineering-conclusion" aria-label="Permalink to &quot;Engineering conclusion&quot;">​</a></h2><p>The OpenHands case showed one consumer principle: <strong>a new event type should not automatically inherit every old subscriber.</strong></p><p>CodeFlowMu&#39;s first-party experiment exposed the adjacent field-level problem: <strong>even when a consumer is entitled to receive an event, it should not automatically inherit every internal field of that event.</strong></p><p>V2.1.2 turns that principle into a Runtime contract:</p><p><strong>internal events preserve facts; the server determines consumer identity; recursive allowlists produce safe projections; unknown fields fail closed; raw events remain only behind authorized diagnostic boundaries.</strong></p><p>This does not weaken observability. It upgrades observability from “copy internal state” to “expose evidence by responsibility.”</p><p>The event happened — that is one fact.</p><p>Who should be allowed to see which parts of it is another fact that must be designed and validated independently.</p><h2 id="evidence-scope-and-primary-sources" tabindex="-1">Evidence scope and primary sources <a class="header-anchor" href="#evidence-scope-and-primary-sources" aria-label="Permalink to &quot;Evidence scope and primary sources&quot;">​</a></h2><ul><li><a href="/joinwell52/en/research/evidence/2026-08-28-event-consumer-visibility">Historical data, old query probe, V2.1.2 engineering update and public release evidence</a>: historical JSON fixture, Reader and check validate frozen material; the public page also maps sanitized implementation facts, B1 independent QA, release gates and residual risks.</li><li><a href="https://github.com/OpenHands/software-agent-sdk/pull/4689" target="_blank" rel="noreferrer">OpenHands SDK PR #4689</a>: provides the external consumer-subscription case with 41 → 1 POSTs; it is not evidence for CodeFlowMu&#39;s field-projection implementation or acceptance.</li><li>CodeFlowMu V2.1.2 implementation, independent-QA and raw release logs remain in the private repository; this public article does not expose inaccessible private links as reader-facing evidence.</li><li>The existence of complete internal data does not prove unauthorized access occurred. This article does not claim that the entire Runtime has eliminated all information risk or that real-network deployments, future unknown consumers or independent Open Edition were included in this validation.</li></ul>',133))])}const b=n(d,[["render",c]]);export{v as __pageData,b as default};
